#include <bits/stdc++.h>
constexpr int N = 3e5 + 10, S = 1.1e7, SS = 2 * S;
int n, q;
int next[SS], val[SS], cnt;
struct queue {
	int head, tail;
	void push(int x) {
		if(head) {
			next[tail] = ++ cnt, val[cnt] = x; tail = cnt;
		} else {
			head = tail = ++ cnt, val[cnt] = x;
		}
		assert(cnt < SS - 100);
	}
	void pop() {head = next[head];}
	int front() {return val[head];}
	bool check() {return head == tail;}
	bool empty() {return head == 0;}
	void clear() {head = tail = 0;}
};
struct node {
	int ls, rs;
	queue fa;
	int val, exit;
	int size, rev;
}a[S];
int tot;
int id[N];
void pushup(int u) {
	a[u].size = a[a[u].ls].size + a[a[u].rs].size;
}
void setR(int u) {
	a[u].rev ^= 1;
	std::swap(a[u].ls, a[u].rs);
}
void setT(int u, int v) {
	a[u].fa.push(v);
}
void pushdown(int u) {
	if(a[u].rev) {
		setR(a[u].ls);
		setR(a[u].rs);
		a[u].rev = 0;
	}
}
int newnode() {
	int u = ++ tot;
	a[u].exit = 2;
	return u;
}
int newleaf() {
	int u = newnode();
	a[u].size = 1;
	return u;
}
int join(int x, int y) {
	int u = newnode();
	a[u].ls = x, a[u].rs = y;
	a[x].fa.push(u);
	a[y].fa.push(u);
	pushup(u);
	return u;
}
auto cut(int x) {
	pushdown(x);
	a[x].exit = 1;
	return std::make_pair(a[x].ls, a[x].rs);
}
int get_val(int u) {
	if(a[u].exit == 0) return 0;
	if(a[u].val != 0) return a[u].val;
	if(a[u].fa.empty()) return 0;
	int ans = 0;
	while(1) {
		ans = get_val(a[u].fa.front());
		if(ans) return ans;
		if(a[u].fa.check()) break;
		a[u].fa.pop();
	}
	if(a[u].exit == 1) {
		a[u].exit = 0;
		a[u].fa.pop();
		a[u].fa.clear();
	}
	return 0;
}
int newtag(int x) {
